// Strofa · bars 88-95 · pattern B
$: s("[bd ~ bd ~] ~ [bd ~ bd ~] ~").bank("AkaiXR10").gain(0.95).lpf(2000).mask(section5).velocity(section5).orbit(1).analyze("kick")
